            customSqlQuery2.Name = "Query_1";
            customSqlQuery2.Sql = resources.GetString("customSqlQuery2.Sql");
            customSqlQuery3.Name = "Query_2";
            customSqlQuery3.Sql = "SELECT  TOP 0 items.id as \'Code\',items.name as \'Item\',items.sale_rate as \'Sale Ra" +
    "te\',si.sold_qty as \'Qty\' from items left join sale_items as si on items.id=si.it" +
    "em_id";
            customSqlQuery4.Name = "Query_3";
            customSqlQuery4.Sql = "SELECT ac.id as \'Code\',ac.name as \'Name\',ac.balance as \'Balance\' from accounts as" +
    " ac left join account_groups as ag on ac.account_group_id=ag.id WHERE ag.nature=" +
    "\'Expense\';\r\n\r\n";
            customSqlQuery5.Name = "agreement_dues";
            customSqlQuery5.Sql = "SELECT emi_date as \'Due Date\',emi_amount as \'Due Amount\' FROM aggrement_dues as a" +
    "d WHERE paid_amount <= 0\r\n";
